using System.Text.Json.Serialization;

namespace Adyen.Models;

public record FraudCheckResult
{
    /// <summary>
    /// The fraud score generated by the risk check.
    /// </summary>
    [JsonPropertyName("accountScore")]
    public required int AccountScore { get; init; }

    /// <summary>
    /// The ID of the risk check.
    /// </summary>
    [JsonPropertyName("checkId")]
    public required int CheckId { get; init; }

    /// <summary>
    /// The name of the risk check.
    /// </summary>
    [JsonPropertyName("name")]
    public required string Name { get; init; }
}
